it('default B applies after fix', () => {
  const sel = container.querySelector('select[data-part=root]');
  expect(sel).toBeTruthy(); expect(sel.value).toBe('b');
});
it('change still works', () => {
  const sel = container.querySelector('select[data-part=root]');
  let changed = null; sel.addEventListener('change', () => { changed = sel.value; });
  sel.value = 'a'; sel.dispatchEvent(new Event('change', { bubbles: true }));
  expect(changed).toBe('a');
});
